<?php
namespace App\Services\Portfolio;use App\Contracts\ProtectedMediaStorage;use App\Models\{Portfolio,User};use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class PortfolioManager{public function __construct(private ProtectedMediaStorage$storage){}public function get(User$owner):Portfolio{$p=Portfolio::firstOrCreate(['studio_owner_id'=>$owner->id],['slug'=>$this->slug($owner),'name'=>$owner->studio_name?:$owner->name]);if(!$p->services()->exists())foreach(config('portfolio.default_services')as$i=>$name)$p->services()->create(['system_key'=>Str::slug($name),'name'=>$name,'sort_order'=>$i,'enabled'=>true]);return$p->fresh(['images.mediaAsset.variants','services']);}private function slug(User$o):string{return Str::slug($o->studio_name?:$o->name).'-'.Str::lower(Str::random(8));}public function save(Portfolio$p,array$d,?UploadedFile$cover,bool$payments):void{DB::transaction(function()use($p,$d,$cover,$payments){$p->lockForUpdate();$update=collect($d)->only(['name','website_url','about_us','currency_code','status'])->all();$update['show_payment_details']=$payments?(bool)($d['show_payment_details']??false):$p->show_payment_details;if($payments)foreach(['upi_id','upi_phone','bank_name','account_holder_name','account_type','ifsc']as$f)$update[$f]=$d[$f]??null;if($payments&&filled($d['account_number']??null))$update['account_number']=$d['account_number'];if(($d['remove_cover']??false)&&!$cover){$this->deleteCover($p);$update+=['cover_disk'=>null,'cover_object_key'=>null,'cover_mime_type'=>null,'cover_size_bytes'=>null,'cover_width'=>null,'cover_height'=>null];}if($cover){$next=$this->cover($p,$cover);$old=$p->cover_object_key;$update+=$next;if($old)$this->storage->delete($old);}$p->update($update);$ids=array_values(array_unique(array_map('intval',$d['image_ids']??[])));$limit=(int)config('portfolio.image_limit',100);if(count($ids)>$limit)throw ValidationException::withMessages(['image_ids'=>"A Portfolio can contain up to {$limit} images."]);$valid=\App\Models\MediaAsset::where('owner_id',$p->studio_owner_id)->where('kind','photo')->where('state','completed')->whereIn('id',$ids)->pluck('id')->all();if(count($valid)!==count($ids))throw ValidationException::withMessages(['image_ids'=>'One or more selected images are unavailable.']);$p->images()->delete();foreach($ids as$i=>$id)$p->images()->create(['media_asset_id'=>$id,'sort_order'=>$i]);$seen=[];foreach($d['services']??[]as$i=>$s){$id=(int)($s['id']??0);$row=$id?$p->services()->whereKey($id)->first():null;if(!$row)$row=$p->services()->make(['is_custom'=>true]);$row->fill(['name'=>$s['name'],'price'=>$s['price']??null,'enabled'=>(bool)$s['enabled'],'sort_order'=>$i,'archived_at'=>null])->save();$seen[]=$row->id;}$p->services()->whereNotIn('id',$seen)->update(['archived_at'=>now()]);});}private function cover(Portfolio$p,UploadedFile$f):array{$bytes=file_get_contents($f->getRealPath());$im=@imagecreatefromstring($bytes);if(!$im)throw ValidationException::withMessages(['cover'=>'The cover must be a valid JPG image.']);$w=imagesx($im);$h=imagesy($im);if($w>3840||$h>2160){imagedestroy($im);throw ValidationException::withMessages(['cover'=>'The cover dimensions may not exceed 3840 × 2160 pixels.']);}imageinterlace($im,true);ob_start();imagejpeg($im,null,88);$out=(string)ob_get_clean();imagedestroy($im);$key='portfolio/covers/'.$p->studio_owner_id.'/'.Str::uuid().'.jpg';$this->storage->put($key,$out,'image/jpeg');return['cover_disk'=>$this->storage->disk(),'cover_object_key'=>$key,'cover_mime_type'=>'image/jpeg','cover_size_bytes'=>strlen($out),'cover_width'=>$w,'cover_height'=>$h];}private function deleteCover(Portfolio$p):void{if($p->cover_object_key)$this->storage->delete($p->cover_object_key);}}
